-- Crear un nuevo usuario con contraseña
CREATE USER miapp WITH PASSWORD 'MiContraseñaSegura123';

-- Crear base de datos
CREATE DATABASE mitienda OWNER miapp;

-- Dar permisos completos
GRANT ALL PRIVILEGES ON DATABASE mitienda TO miapp;

-- Conectar a la base de datos como el nuevo usuario
\c mitienda miapp

-- Insertar datos
INSERT INTO usuarios (nombre, email, password_hash) VALUES
    ('Ana García', 'ana@ejemplo.com', 'hash123'),
    ('Carlos López', 'carlos@ejemplo.com', 'hash456');

INSERT INTO productos (nombre, precio, stock, categoria) VALUES
    ('Portátil Pro X', 1299.99, 15, 'Electrónica'),
    ('Teclado Mecánico', 89.95, 42, 'Electrónica'),
    ('Silla Ergonómica', 349.00, 8, 'Muebles');

-- Consultas básicas
SELECT * FROM productos WHERE precio < 100;
SELECT nombre, precio FROM productos WHERE categoria = 'Electrónica' ORDER BY precio;

-- JOIN: pedidos con nombre de usuario
SELECT u.nombre, p.id, p.total, p.estado
FROM pedidos p
JOIN usuarios u ON p.usuario_id = u.id
WHERE p.estado = 'pendiente';
